import { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Swal from "sweetalert2";

const DETECCIONES_RECIENTES = [
  { id: 1, fecha: "24/07/2025", hora: "08:45 a.m.", imagen: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100", diagnostico: "Sigatoka Negra", severidad: "Moderado", lote: "Lote 6 - Bloque A", usuario: "Carlos Mendoza" },
  { id: 2, fecha: "23/07/2025", hora: "04:30 p.m.", imagen: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6?q=80&w=100", diagnostico: "Sigatoka Negra", severidad: "Severo",   lote: "Lote 5 - Bloque D", usuario: "Carlos Mendoza" },
  { id: 3, fecha: "23/07/2025", hora: "11:20 a.m.", imagen: "https://images.unsplash.com/photo-1471193945509-9ad0617afabf?q=80&w=100", diagnostico: "Sana",           severidad: "Leve",     lote: "Lote 4 - Bloque B", usuario: "Carlos Mendoza" },
];

const severidadConfig = {
  Moderado: { bg: "bg-amber-100", text: "text-amber-700", border: "border-amber-200" },
  Severo:   { bg: "bg-red-100",   text: "text-red-600",  border: "border-red-200" },
  Leve:     { bg: "bg-emerald-100", text: "text-emerald-700", border: "border-emerald-200" },
};

export default function Deteccion() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [image, setImage] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [cameraOpen, setCameraOpen] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [resultado, setResultado] = useState(null);
  const [captureMode, setCaptureMode] = useState("camara");
  const [lote, setLote] = useState("Lote 7 - Bloque B");
  const [tipoHoja, setTipoHoja] = useState("Hoja 3 (Madura)");
  const [observaciones, setObservaciones] = useState("Manchas extendidas en el centro y borde de la hoja.");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);
  const streamRef = useRef(null);

  const fullName = user?.displayName || user?.email?.split("@")[0] || "Carlos Mendoza";
  const storageKey = `scans_${user?.uid || user?.email || "guest"}`;

  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;
      setCameraOpen(true);
      setTimeout(() => { if (videoRef.current) videoRef.current.srcObject = stream; }, 100);
    } catch {
      Swal.fire({ title: "Sin acceso a la cámara", text: "Verifica los permisos.", icon: "error", confirmButtonColor: "#226b22" });
    }
  };

  const closeCamera = () => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    setCameraOpen(false);
  };

  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0);
    canvas.toBlob(blob => {
      const file = new File([blob], "captura.jpg", { type: "image/jpeg" });
      setImageFile(file);
      setImage(URL.createObjectURL(blob));
      closeCamera();
    }, "image/jpeg");
  };

  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file || !file.type.startsWith("image/")) return;
    setImageFile(file);
    setImage(URL.createObjectURL(file));
    setResultado(null);
  };

  const toBase64 = (file) => new Promise((res, rej) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => res(reader.result);
    reader.onerror = rej;
  });

  const analizar = async () => {
    if (!imageFile) {
      Swal.fire({ title: "Sin imagen", text: "Primero carga o captura una imagen.", icon: "warning", confirmButtonColor: "#226b22" });
      return;
    }
    setAnalyzing(true);
    await new Promise(r => setTimeout(r, 2000));

    const base64 = await toBase64(imageFile);
    const newScan = {
      id: Date.now(),
      enfermedad: "Sigatoka Negra",
      nivel_riesgo: "Severo",
      confianza: 94.6,
      planta: "Banano",
      lote,
      tipoHoja,
      observaciones,
      fecha: new Date().toLocaleDateString("es-EC", { day: "2-digit", month: "2-digit", year: "numeric" }),
      hora: new Date().toLocaleTimeString("es-EC", { hour: "2-digit", minute: "2-digit" }),
      imageUrl: base64,
    };

    const prev = JSON.parse(localStorage.getItem(storageKey) || "[]");
    prev.unshift(newScan);
    localStorage.setItem(storageKey, JSON.stringify(prev.slice(0, 20)));

    setResultado({
      diagnostico: "Sigatoka Negra",
      severidad: "Severo",
      confianza: 94.6,
      caracteristicas: [
        "Manchas necróticas grandes",
        "Presencia de halo amarillo",
        "Afectación avanzada del tejido foliar",
      ],
      nota: "El modelo de IA ha identificado signos de Sigatoka Negra con un alto nivel de confianza.",
    });
    setAnalyzing(false);
  };

  const guardarResultado = () => {
    if (!resultado) {
      Swal.fire({ title: "Sin resultado", text: "Primero analiza una imagen.", icon: "warning", confirmButtonColor: "#226b22" });
      return;
    }
    Swal.fire({
      title: "✅ Resultado guardado",
      text: "El diagnóstico ha sido registrado correctamente.",
      icon: "success",
      confirmButtonColor: "#226b22",
    });
  };

  return (
    <div className="min-h-screen bg-white p-6 space-y-6">

      {/* TÍTULO */}
      <div className="flex items-start gap-3">
        <div className="w-12 h-12 rounded-2xl bg-green-100 flex items-center justify-center text-2xl shrink-0">
          🔬
        </div>
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Detección de Sigatoka Negra</h1>
          <p className="text-sm text-gray-500 mt-0.5">
            Captura y analiza imágenes de hojas de banano para identificar la presencia de Sigatoka Negra.
          </p>
        </div>
      </div>

      {/* CÁMARA EN VIVO */}
      {cameraOpen && (
        <div className="fixed inset-0 bg-black z-50 flex flex-col">
          <div className="flex items-center gap-3 px-4 py-3 bg-black/60">
            <button onClick={closeCamera} className="w-9 h-9 rounded-full bg-white/20 text-white flex items-center justify-center hover:bg-white/30 transition">✕</button>
            <span className="text-white text-sm">Enfoca la hoja de banano</span>
          </div>
          <video ref={videoRef} autoPlay playsInline className="flex-1 w-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />
          <div className="bg-black/70 p-6 flex items-center justify-center gap-10">
            <button onClick={closeCamera} className="w-12 h-12 rounded-full bg-white/20 text-white text-xl flex items-center justify-center hover:bg-white/30 transition">←</button>
            <button onClick={capturePhoto} className="rounded-full bg-white border-4 border-white/40 shadow-lg hover:scale-105 transition" style={{ width: 72, height: 72 }} />
            <div className="w-12 h-12" />
          </div>
        </div>
      )}

      {/* CONTENIDO PRINCIPAL - 3 COLUMNAS */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* COLUMNA 1 - Captura */}
        <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
          <h2 className="font-bold text-gray-800 text-lg mb-4 flex items-center gap-2">
            <span className="w-7 h-7 rounded-full bg-green-700 text-white flex items-center justify-center text-xs font-bold">1</span>
            Captura de Imagen
          </h2>

          <div className="flex gap-2 mb-4">
            <button
              onClick={() => { setCaptureMode("camara"); openCamera(); }}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-semibold transition ${
                captureMode === "camara" ? "bg-green-700 text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              📷 Cámara
            </button>
            <button
              onClick={() => { setCaptureMode("galeria"); fileInputRef.current.click(); }}
              className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-semibold transition ${
                captureMode === "galeria" ? "bg-green-700 text-white" : "bg-gray-100 text-gray-600 hover:bg-gray-200"
              }`}
            >
              🖼️ Galería
            </button>
            <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFile} className="hidden" />
          </div>

          <div className="rounded-2xl overflow-hidden bg-gray-50 border border-gray-200 mb-4" style={{ height: 220 }}>
            {image ? (
              <div className="relative h-full">
                <img src={image} alt="Captura" className="w-full h-full object-cover" />
                <button
                  onClick={() => { setImage(null); setImageFile(null); setResultado(null); }}
                  className="absolute top-2 right-2 w-8 h-8 rounded-full bg-black/50 text-white flex items-center justify-center hover:bg-black/70 transition"
                >✕</button>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center gap-2 text-gray-400">
                <span className="text-5xl">📷</span>
                <p className="text-sm font-medium">Sin imagen cargada</p>
                <p className="text-xs">Usa cámara o galería</p>
              </div>
            )}
          </div>

          <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 mb-4">
            <p className="text-sm font-semibold text-blue-800 mb-2 flex items-center gap-2">
              💡 Consejos para una mejor captura
            </p>
            <div className="space-y-1.5">
              <div className="flex items-center gap-2 text-sm text-blue-700">
                <span className="text-green-600 text-xs">✓</span> Usa buena iluminación
              </div>
              <div className="flex items-center gap-2 text-sm text-blue-700">
                <span className="text-green-600 text-xs">✓</span> Enfoca únicamente la hoja
              </div>
              <div className="flex items-center gap-2 text-sm text-blue-700">
                <span className="text-green-600 text-xs">✓</span> Evita sombras y desenfoques
              </div>
              <div className="flex items-center gap-2 text-sm text-blue-700">
                <span className="text-green-600 text-xs">✓</span> Asegúrate de que la hoja esté completa
              </div>
            </div>
          </div>

          <button
            onClick={image ? analizar : openCamera}
            disabled={analyzing}
            className="w-full py-3.5 bg-green-700 hover:bg-green-800 text-white rounded-xl font-semibold text-sm flex items-center justify-center gap-2 disabled:opacity-60 transition"
          >
            {analyzing ? (
              <><span className="w-4 h-4 border-2 border-white/40 border-t-white rounded-full animate-spin" /> Analizando...</>
            ) : image ? (
              <><span>🔍</span> Analizar imagen</>
            ) : (
              <><span>📷</span> Capturar Imagen</>
            )}
          </button>
        </div>

        {/* COLUMNA 2 - Resultado */}
        <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
          <h2 className="font-bold text-gray-800 text-lg mb-4 flex items-center gap-2">
            <span className="w-7 h-7 rounded-full bg-green-700 text-white flex items-center justify-center text-xs font-bold">2</span>
            Resultado del Análisis
          </h2>

          {resultado ? (
            <div className="space-y-4">
              <div className="bg-red-50 border border-red-200 rounded-2xl p-5 text-center">
                <p className="text-xs text-gray-500 font-medium mb-1">Diagnóstico</p>
                <div className="flex items-center justify-center gap-3">
                  <div className="w-14 h-14 rounded-full bg-red-100 flex items-center justify-center text-3xl">🍃</div>
                  <p className="text-2xl font-bold text-red-500">{resultado.diagnostico}</p>
                </div>
              </div>

              <div className="bg-gray-50 rounded-2xl p-5">
                <p className="text-xs text-gray-500 font-medium mb-2">Nivel de Severidad</p>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center text-white text-lg font-bold shrink-0">!</div>
                  <span className="bg-red-100 text-red-600 border border-red-200 px-5 py-2 rounded-full text-sm font-bold">
                    {resultado.severidad}
                  </span>
                </div>
              </div>

              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <p className="text-sm text-gray-600 font-medium">Confianza del modelo (Accuracy)</p>
                </div>
                <p className="text-4xl font-bold text-green-700 mb-2">{resultado.confianza}%</p>
                <div className="relative h-3 bg-gray-200 rounded-full overflow-hidden">
                  <div className="absolute inset-0 flex justify-between px-1 items-center">
                    <span className="text-[9px] text-gray-400">0%</span>
                    <span className="text-[9px] text-gray-400">50%</span>
                    <span className="text-[9px] text-gray-400">100%</span>
                  </div>
                  <div className="h-full bg-green-700 rounded-full transition-all duration-700" style={{ width: `${resultado.confianza}%` }} />
                </div>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-16 gap-4 text-gray-300">
              <span className="text-6xl">🔬</span>
              <p className="text-sm text-center max-w-xs">El resultado aparecerá aquí después de analizar la imagen</p>
            </div>
          )}
        </div>

        {/* COLUMNA 3 - Registro */}
        <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm space-y-6">
          <div>
            <h2 className="font-bold text-gray-800 text-lg mb-4 flex items-center gap-2">
              <span className="w-7 h-7 rounded-full bg-green-700 text-white flex items-center justify-center text-xs font-bold">3</span>
              Información del Registro
            </h2>

            <div className="space-y-4">
              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-lg bg-green-50 flex items-center justify-center text-lg shrink-0">🌿</div>
                <div className="flex-1">
                  <p className="text-xs text-gray-400 font-medium">Lote</p>
                  <select
                    value={lote}
                    onChange={e => setLote(e.target.value)}
                    className="text-sm font-semibold text-gray-800 bg-transparent outline-none w-full cursor-pointer"
                  >
                    {["Lote 7 - Bloque B", "Lote 6 - Bloque A", "Lote 5 - Bloque D", "Lote 4 - Bloque B", "Lote 3 - Bloque C"].map(l => (
                      <option key={l}>{l}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="border-t border-gray-100" />

              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-lg bg-green-50 flex items-center justify-center text-lg shrink-0">📅</div>
                <div>
                  <p className="text-xs text-gray-400 font-medium">Fecha y Hora</p>
                  <p className="text-sm font-semibold text-gray-800">
                    {new Date().toLocaleDateString("es-EC", { day: "2-digit", month: "2-digit", year: "numeric" })} {new Date().toLocaleTimeString("es-EC", { hour: "2-digit", minute: "2-digit" })}
                  </p>
                </div>
              </div>

              <div className="border-t border-gray-100" />

              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-lg bg-green-50 flex items-center justify-center text-lg shrink-0">🍃</div>
                <div className="flex-1">
                  <p className="text-xs text-gray-400 font-medium">Tipo de Hoja</p>
                  <select
                    value={tipoHoja}
                    onChange={e => setTipoHoja(e.target.value)}
                    className="text-sm font-semibold text-gray-800 bg-transparent outline-none w-full cursor-pointer"
                  >
                    {["Hoja 1 (Joven)", "Hoja 2 (Intermedia)", "Hoja 3 (Madura)", "Hoja 4 (Vieja)"].map(h => (
                      <option key={h}>{h}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="border-t border-gray-100" />

              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-lg bg-green-50 flex items-center justify-center text-lg shrink-0">📍</div>
                <div>
                  <p className="text-xs text-gray-400 font-medium">Ubicación (GPS)</p>
                  <p className="text-sm font-semibold text-gray-800">Latitud: -2.137456</p>
                  <p className="text-sm font-semibold text-gray-800">Longitud: -79.547821</p>
                </div>
              </div>

              <div className="border-t border-gray-100" />

              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-lg bg-green-50 flex items-center justify-center text-lg shrink-0">📝</div>
                <div className="flex-1">
                  <p className="text-xs text-gray-400 font-medium mb-1">Observaciones</p>
                  <textarea
                    value={observaciones}
                    onChange={e => setObservaciones(e.target.value)}
                    placeholder="Manchas extendidas en el centro y borde de la hoja..."
                    rows={2}
                    className="w-full text-sm text-gray-700 bg-gray-50 rounded-lg p-2 outline-none border border-gray-200 focus:border-green-300 resize-none"
                  />
                </div>
              </div>

              <div className="border-t border-gray-100" />

              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-lg bg-green-50 flex items-center justify-center text-lg shrink-0">👤</div>
                <div>
                  <p className="text-xs text-gray-400 font-medium">Registrado por</p>
                  <p className="text-sm font-semibold text-gray-800">{fullName}</p>
                </div>
              </div>
            </div>
          </div>

          {/* ACCIONES */}
          <div>
            <h2 className="font-bold text-gray-800 text-sm mb-3">Acciones</h2>
            <div className="space-y-2">
              <button
                onClick={guardarResultado}
                disabled={!resultado}
                className="w-full py-3 bg-green-700 hover:bg-green-800 text-white rounded-xl text-sm font-semibold flex items-center justify-center gap-2 disabled:opacity-40 transition"
              >
                💾 Guardar Resultado
              </button>
              <button
                onClick={() => { setImage(null); setImageFile(null); setResultado(null); setObservaciones(""); }}
                className="w-full py-3 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 rounded-xl text-sm font-semibold flex items-center justify-center gap-2 transition"
              >
                📷 Nueva Detección
              </button>
              <button
                onClick={() => navigate("/scan")}
                className="w-full py-3 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 rounded-xl text-sm font-semibold flex items-center justify-center gap-2 transition"
              >
                📋 Ver Historial
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* DETECCIONES RECIENTES */}
      <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden shadow-sm">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
          <h2 className="font-bold text-gray-800">Detecciones Recientes</h2>
          <button onClick={() => navigate("/scan")} className="text-green-700 text-sm font-medium hover:underline">Ver todas</button>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="bg-gray-50 text-gray-500 text-xs font-semibold">
                <th className="text-left px-6 py-3">Fecha</th>
                <th className="text-left px-4 py-3">Imagen</th>
                <th className="text-left px-4 py-3">Diagnóstico</th>
                <th className="text-left px-4 py-3">Severidad</th>
                <th className="text-left px-4 py-3">Lote</th>
                <th className="text-left px-4 py-3">Usuario</th>
                <th className="text-center px-4 py-3">Acción</th>
              </tr>
            </thead>
            <tbody>
              {DETECCIONES_RECIENTES.map((d, i) => {
                const sev = severidadConfig[d.severidad] || severidadConfig.Leve;
                return (
                  <tr key={d.id} className={`border-t border-gray-100 hover:bg-gray-50 transition ${i % 2 === 0 ? 'bg-white' : 'bg-gray-50/50'}`}>
                    <td className="px-6 py-3">
                      <p className="font-medium text-gray-800">{d.fecha}</p>
                      <p className="text-xs text-gray-400">{d.hora}</p>
                    </td>
                    <td className="px-4 py-3">
                      <img src={d.imagen} alt="" className="w-12 h-12 rounded-xl object-cover" />
                    </td>
                    <td className={`px-4 py-3 font-semibold ${d.diagnostico === "Sigatoka Negra" ? "text-red-500" : "text-emerald-600"}`}>
                      {d.diagnostico}
                    </td>
                    <td className="px-4 py-3">
                      <span className={`font-semibold text-xs px-3 py-1.5 rounded-full border ${sev.bg} ${sev.text} ${sev.border}`}>
                        {d.severidad}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-gray-600">{d.lote}</td>
                    <td className="px-4 py-3 text-gray-600">{d.usuario}</td>
                    <td className="px-4 py-3 text-center">
                      <button
                        onClick={() => navigate(`/result/${d.id}`)}
                        className="w-8 h-8 rounded-full bg-green-50 text-green-600 flex items-center justify-center mx-auto hover:bg-green-100 transition"
                      >
                        👁️
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
